/*
 * C2KOR - language state manager
 * Reads data/site-content.json (embedded via assets/js/site-content-data.js,
 * generated by tools/bundle_site_content.py) and manages which language is
 * active. Does NOT render content itself — see content-render.js for that.
 *
 * Language rules (per CLAUDE_CODE_INSTRUCTIONS.md):
 * - English always renders first on a brand-new visit, regardless of
 *   browser language. Only a language marked complete in meta.languages
 *   and previously chosen via localStorage overrides that.
 * - Korean is always second in the language switcher; the rest follow
 *   meta.languageOrder. Languages not marked "complete" are not shown.
 */
(function (global) {
  var STORAGE_KEY = "sfw_lang";

  function getRoot() {
    return global.SFW_SITE_CONTENT || null;
  }

  function getMeta() {
    var root = getRoot();
    return (root && root.meta) || { languageOrder: ["en"], languages: { en: { status: "complete" } }, pageOrder: [] };
  }

  function isComplete(lang) {
    var meta = getMeta();
    var entry = meta.languages && meta.languages[lang];
    return !!entry && entry.status === "complete";
  }

  function getAvailableLanguages() {
    var meta = getMeta();
    return (meta.languageOrder || []).filter(isComplete);
  }

  function detectInitialLang() {
    var stored = null;
    try { stored = localStorage.getItem(STORAGE_KEY); } catch (e) {}
    if (stored && isComplete(stored)) return stored;
    return "en";
  }

  function setStoredLang(lang) {
    try { localStorage.setItem(STORAGE_KEY, lang); } catch (e) {}
  }

  function getLangBlock(lang) {
    var root = getRoot();
    if (!root) return null;
    return root[lang] || root.en || null;
  }

  function getHomeData(lang) {
    var block = getLangBlock(lang);
    return (block && block.home) || null;
  }

  function getPageData(lang, pageId) {
    var block = getLangBlock(lang);
    var page = block && block.pages && block.pages[pageId];
    if (page) return page;
    // Fall back to English content for a page missing in this language.
    var enBlock = getLangBlock("en");
    return (enBlock && enBlock.pages && enBlock.pages[pageId]) || null;
  }

  var currentLang = detectInitialLang();

  var SFWi18n = {
    getMeta: getMeta,
    isComplete: isComplete,
    getAvailableLanguages: getAvailableLanguages,
    getHomeData: getHomeData,
    getPageData: getPageData,
    getLang: function () { return currentLang; },
    setLang: function (lang) {
      if (!isComplete(lang)) return currentLang;
      currentLang = lang;
      setStoredLang(lang);
      document.documentElement.setAttribute("lang", lang);
      document.dispatchEvent(new CustomEvent("sfw:lang-changed", { detail: { lang: lang } }));
      return currentLang;
    },
    init: function () {
      if (!getRoot()) {
        console.error("[i18n] window.SFW_SITE_CONTENT is missing. Is assets/js/site-content-data.js loaded before i18n.js?");
      }
      document.documentElement.setAttribute("lang", currentLang);
      document.dispatchEvent(new CustomEvent("sfw:lang-changed", { detail: { lang: currentLang } }));
      return currentLang;
    }
  };

  global.SFWi18n = SFWi18n;
})(window);
